-- Baseline of the schema previously generated by Hibernate (ddl-auto: update).
-- Databases that already exist are baselined at version 1 and skip this file.
CREATE TABLE IF NOT EXISTS users (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email               VARCHAR(255) NOT NULL UNIQUE,
    password            VARCHAR(255) NOT NULL,
    name                VARCHAR(255) NOT NULL,
    bio                 VARCHAR(500),
    profile_picture_url VARCHAR(255),
    created_at          TIMESTAMP(6),
    updated_at          TIMESTAMP(6)
);

CREATE TABLE IF NOT EXISTS skills (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(255) NOT NULL UNIQUE,
    category    VARCHAR(255) NOT NULL,
    description VARCHAR(500)
);

CREATE TABLE IF NOT EXISTS user_skills (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id           BIGINT NOT NULL REFERENCES users (id),
    skill_id          BIGINT NOT NULL REFERENCES skills (id),
    skill_type        VARCHAR(255) NOT NULL,
    proficiency_note  VARCHAR(500),
    CONSTRAINT uk_user_skill_type UNIQUE (user_id, skill_id, skill_type)
);
